"""Assemble the reviewed original-authored dressing handoff; no publication."""
from pathlib import Path
import json,hashlib,zipfile
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1]
a=json.loads((ROOT/'validation'/'authoring-inventory.json').read_text());fresh=json.loads((ROOT/'validation'/'fresh-import-checks.json').read_text());static=json.loads((ROOT/'validation'/'static-glb-checks.json').read_text())
assert len(a)==len(fresh)==len(static['assets'])==7
for asset in a:
 f=next(x for x in fresh if x['asset']==asset['name']+'.glb');s=next(x for x in static['assets'] if x['asset']==asset['name']+'.glb')
 assert asset['triangles']==f['triangles']==s['triangles']
 assert f['finite_positions_normals_uvs'] and f['non_unit_vertex_normals']==f['degenerate_triangles']==0 and abs(f['ground_min_z'])<1e-6
 assert s['positions_normals_uvs_finite'] and s['all_materials_opaque'] and s['normals_unit_within_0_002']
 assert hashlib.sha256((ROOT/'assets'/s['asset']).read_bytes()).hexdigest()==s['glb_sha256']
for name in ['horde-bark-original-basecolor-512.png','horde-bark-original-normal-512.png','horde-bark-original-roughness-512.png','horde-alder-original-basecolor-512.png']:
 assert (ROOT/'textures'/name).read_bytes()==((ROOT.parents[1]/'forest/trees/original-tree-pair-v1/textures')/name).read_bytes()
# Actual fresh-import render contact sheet, with labels added around the pixels.
fontp='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
font=ImageFont.truetype(fontp,22);small=ImageFont.truetype(fontp,15);head=ImageFont.truetype(fontp,34)
W=1600;cw=380;ch=438;pad=20;top=115
sheet=Image.new('RGB',(W,top+ch*2+40),(26,32,35));d=ImageDraw.Draw(sheet)
d.text((20,21),'HORDE1.7 FOREST DRESSING',font=head,fill=(227,226,209))
d.text((22,70),'7 original low-poly mesh source candidates | Fresh GLB imports | 4,602 triangles total',font=font,fill=(175,188,169))
labels={'bh_rock_low_boulder':'Low boulder','bh_rock_upright_crag':'Upright crag','bh_rock_split_shelf':'Split shelf','bh_log_fallen_trunk':'Fallen trunk','bh_root_branch_tangle':'Root / branch piece','bh_fern_open_clump':'Open fern','bh_fern_small_clump':'Small fern'}
for i,asset in enumerate(a):
 x=pad+(i%4)*(cw+20);y=top+(i//4)*ch
 im=Image.open(ROOT/'previews'/f"{asset['name']}-closeup.png").convert('RGB').resize((cw,cw),Image.Resampling.LANCZOS);sheet.paste(im,(x,y))
 d.text((x,y+386),labels[asset['name']],font=font,fill=(227,226,209));d.text((x,y+416),f"{asset['triangles']} tri | {asset['materials']} material(s)",font=small,fill=(175,188,169))
x=pad+3*(cw+20);y=top+ch
for j,line in enumerate(['Opaque real 3D geometry','No cards or billboards','Original shared 512px maps','Editable Blender + generators','','Source candidates only','Engine / mobile / RT untested','No collision mesh supplied']):d.text((x+15,y+70+j*32),line,font=font if j in (0,5) else small,fill=(198,207,185))
sheet.save(ROOT/'previews'/'Horde-1.7-forest-dressing-contact-sheet.jpg',quality=92)
lines=['# The Horde 1.7: original forest dressing\n','Seven bounded low-poly source candidates: three rock masters, one fallen trunk, one root/branch piece, and two fern clumps. This package does not claim complete Horde 1.7 coverage, engine integration, or hero close-up quality.\n','## Asset inventory\n','Dimensions are Blender X/Y/Z in meters (width/depth/height). Portable GLBs are Y-up and grounded at Y=0. Each asset has a horizontal bounds-centered ground origin.\n','| Asset | Triangles | Materials | Source maps | Dimensions (m) |','|---|---:|---:|---:|---|']
for x in a:lines.append(f"| {labels[x['name']]} | {x['triangles']} | {x['materials']} | {x['source_texture_count']} | "+' × '.join(f'{v:.3f}' for v in x['dimensions_blender_xyz_m'])+' |')
lines+=['','Total: 4,602 triangles across the seven masters. Four original material families: slate, bark, weathered endgrain, and foliage. Ten unique source maps, all 512×512. There are nine material primitives across the seven GLBs; this is a file inventory, not a measured engine draw-call count.','', '## Contents and reproduction','- assets/: Seven portable textured GLBs. Each embeds required textures for standalone use.','- source/Horde-1.7-forest-dressing.blend: Editable mesh scene, exploded for inspection. Texture links are package-relative.','- source/build_forest_dressing.py: Deterministic original geometry/export generator, Blender 4.3.2. Run with blender -b --python source/build_forest_dressing.py.','- source/generate_stone_maps.py and generate_endgrain_maps.py: Original texture generators requiring Python, NumPy, and Pillow. The provided maps can be used directly.','- source/shared_tree_material_provenance.py: Preserved upstream original tree authoring source, for lineage only; it is not the dressing build entrypoint. Shared map bytes are copied unchanged from the original tree-pair package.','- source/render_wireframe_evidence.py: Renders readable unlit actual-triangle wire evidence after the standard closeup/silhouette render script.', '- previews/: Actual fresh-import closeup, wireframe, and silhouette views for every asset, plus log cut-end detail and a contact sheet.','- validation/: Machine-readable source, binary GLB, fresh-import, pixel-range, and shared-texture lineage evidence.','', '## Shared texture handling','Bark uses the exact approved original tree-pair maps: basecolor sRGB, normal and roughness Non-Color, tangent normal strength 0.70, metallic 0, IOR 1.4. Cylindrical UV U wraps one circumference and V repeats per 1.7m of path length. Ferns reuse the original alder green map, roughness 0.84. Stone and endgrain are newly authored procedural PBR sets. Cut faces use their own endgrain map and planar UVs.','', 'The GLBs repeat shared maps for portability. An importer should reuse shared maps/materials using the included lineage names and hashes. Across the kit there are 10 unique embedded images: 7,864,320 decoded RGB bytes (7.5 MiB), or a conservative 10 MiB RGBA8 allocation before mipmaps (about 13.33 MiB with full mip chains). These are format estimates, not measured GPU residency. Actual engine format, compression, mips, and deduplication determine runtime use.','', '## Verified and unverified','Verified: GLB v2 structure; finite positions, normals and UVs; normalized stored normals; explicit triangle/material/image counts; opaque materials; 512px embedded images; ground-origin bounds; fresh Blender GLB import; no near-degenerate imported triangles; actual imported-mesh renders; source-map lineage hashes.','', 'The game-dev CLI was absent. These are independent Blender/Python checks, not game-dev canonical-package validation, Khronos validation, Horde runtime validation, or GPU/mobile performance certification. Native/mobile/RT behavior remains untested. There is no collision mesh or physics certification in this package. No integration, Git publication, or public release was performed.','', '## Visual and topology limits','These are restrained low-poly dressing candidates. Close-up limitations include hard rock faceting, visible repeated bark structure, simple tube intersections at branch joins, and sparse angular fern pinnae. Fern pinnae are genuinely closed volumetric lenses, not alpha cards. Logs/roots consist of intersecting closed components rather than a single Boolean-unioned watertight shell. Rocks include a deliberately two-component split shelf. No claim is made that intersections are physically or collision-ready.','', 'The project tree reference was used only as a visual direction cue. None of its pixels, impostor planes, or geometry are shipped as runtime content. The existing approved stump is not duplicated.']
(ROOT/'README.md').write_text('\n'.join(lines)+'\n')
(ROOT/'ORIGINAL-AUTHORSHIP.txt').write_text('Original-authored project asset handoff for The Horde 1.7, prepared 2026-10-06.\n\nAll geometry in this package and the stone/endgrain maps were authored procedurally with deterministic local Blender/Python scripts for this project. Bark and foliage maps are original project-authored shared maps from the companion tree-pair source, preserved with source and hashes. No third-party mesh or map is included. No paid generation/provider call was used for this dressing kit.\n\nProject-owned/original-authorship notice only. This handoff does not newly dedicate the assets to CC0, select an unrelated public license, or authorize publication. Existing user/project rights and instructions govern use.\n')
spec=json.loads((ROOT/'source'/'asset-spec.json').read_text());spec['status']='Original source candidates completed and independently checked; engine integration/performance untested';spec['actual_total_triangles']=4602;spec['materials']['shared_bark']='Approved original tree-pair maps, copied unchanged with hashes';spec['materials']['shared_leaf']='Approved original alder map, copied unchanged with hashes';spec['materials']['stone']='Original deterministic 512px PBR set';spec['materials']['cut_wood']='Original deterministic 512px weathered endgrain PBR set';(ROOT/'source'/'asset-spec.json').write_text(json.dumps(spec,indent=2)+'\n')
files=[]
for p in ROOT.rglob('*'):
 if not p.is_file():continue
 rel=p.relative_to(ROOT)
 if p.suffix in ['.glb','.blend','.py','.json','.png','.jpg','.md','.txt'] and p.name not in ['sha256-manifest.json','package-receipt.json'] and p.name not in ['stone-material-test.png','briarhold-forest-dressing-contact-sheet.jpg','briarhold_forest_dressing.blend']:files.append(p)
manifest={str(p.relative_to(ROOT)):{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(files)}
(ROOT/'sha256-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');files.append(ROOT/'sha256-manifest.json')
zip_path=ROOT.parent/'Horde-1.7-original-forest-dressing-v1.zip'
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
 for p in sorted(files):z.write(p,str(Path('Horde-1.7-original-forest-dressing-v1')/p.relative_to(ROOT)))
with zipfile.ZipFile(zip_path) as z:assert z.testzip() is None;assert len(z.namelist())==len(files)
assert zip_path.stat().st_size<32*1024*1024
receipt={'zip':str(zip_path),'bytes':zip_path.stat().st_size,'sha256':hashlib.sha256(zip_path.read_bytes()).hexdigest(),'members':len(files),'zip_crc_test':'pass','source_manifest_members':len(manifest),'under_32_mib':True}
(ROOT/'package-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2))
